    // Ngay lam task
    private Date date;

    // So gio lam (To - From)
    private double time;

    // Nguoi lam task
    private String assign;

    // Nguoi review task
    private String reviewer;

    // Tao dong bang rong (JavaBean)
    public ResponseDTO() {
    }

    // Tra ve ID cua task
    public int getId() {
        return id;
    }

    // Gan ID cua task
    public void setId(int id) {
        this.id = id;
    }

    // Tra ve loai task
    public TaskType getTaskType() {
        return taskType;
    }

    // Gan loai task
    public void setTaskType(TaskType taskType) {
        this.taskType = taskType;
    }

    // Tra ve ten requirement
    public String getRequirementName() {
        return requirementName;
    }

    // Gan ten requirement
    public void setRequirementName(String requirementName) {
        this.requirementName = requirementName;
    }

    // Tra ve ngay lam task
    public Date getDate() {
        return date;
    }

    // Gan ngay lam task
    public void setDate(Date date) {
        this.date = date;
    }

    // Tra ve so gio lam (To - From)
    public double getTime() {
        return time;
    }

    // Gan so gio lam (To - From)
    public void setTime(double time) {
        this.time = time;
    }

    // Tra ve nguoi lam task
    public String getAssign() {
        return assign;
    }

    // Gan nguoi lam task
    public void setAssign(String assign) {
        this.assign = assign;
    }

    // Tra ve nguoi review task
    public String getReviewer() {
        return reviewer;
    }

    // Gan nguoi review task
    public void setReviewer(String reviewer) {
        this.reviewer = reviewer;
    }

    // Ghep 1 dong bang theo dung dinh dang cot cua tieu de
    @Override
    public String toString() {
        // Dinh dang ngay dd-MM-yyyy
        SimpleDateFormat dateFormat = new SimpleDateFormat(Constants.DATE_FORMAT_PATTERN);

        // Ghep cac cot: ID, ten, loai, ngay, gio, nguoi lam, nguoi review
        return String.format(Constants.TABLE_FORMAT, getId(), getRequirementName(),
                getTaskType().getName(), dateFormat.format(getDate()), getTime(), getAssign(),
                getReviewer());
    }
}

