package view;

import constants.Constants;
import constants.Message;
import dto.ResponseDTO;
import java.util.ArrayList;
import java.util.List;

/**
 * Man hinh: chi in ket qua Controller dua vao qua thuoc tinh; display() khong tham so,
 * goi 1 lan cho 1 luong: in cau thong bao, HOAC in bang task.
 *
 * @author CuongThai Academy
 */
public class TaskView {

    // Cac dong bang task can in
    private List<ResponseDTO> responseList;

    // Cau thong bao can in (rong thi in bang)
    private String message;

    // Constructor: chua co gi de in
    public TaskView() {
        responseList = new ArrayList<>();
        message = "";
    }

    // Controller dua cac dong bang vao
    public void setResponseList(List<ResponseDTO> responseList) {
        this.responseList = responseList;
    }

    // Controller dua cau thong bao vao
    public void setMessage(String message) {
        this.message = message;
    }

    // In ket qua cua 1 luong roi xoa cau thong bao de luong sau bat dau sach
    public void display() {
        // Co cau thong bao thi chi in cau do
        if (!message.isEmpty()) {
            System.out.println(message);
        } else {
            // Bang: tieu de, ten cot (cung dinh dang voi tung dong), roi tung dong task
            System.out.println(Message.TITLE_DISPLAY);
            System.out.println(String.format(Constants.TABLE_FORMAT, Message.COLUMN_ID,
                    Message.COLUMN_NAME, Message.COLUMN_TASK_TYPE, Message.COLUMN_DATE,
                    Message.COLUMN_TIME, Message.COLUMN_ASSIGNEE, Message.COLUMN_REVIEWER));

            // Moi task 1 dong
            for (ResponseDTO responseDTO : responseList) {
                System.out.println(responseDTO);
            }
        }

        message = "";
    }
}

