 * @author CuongThai Academy
 */
public enum TaskType {

    // Loai 1: viet code
    CODE(1, "Code"),

    // Loai 2: kiem thu
    TEST(2, "Test"),

    // Loai 3: thiet ke
    DESIGN(3, "Design"),

    // Loai 4: review
    REVIEW(4, "Review");

    // Ma loai task (1 den 4)
    private int id;

    // Ten loai task in ra bang
    private String name;

    // Tao 1 loai task voi ma va ten
    private TaskType(int id, String name) {
        this.id = id;
        this.name = name;
    }

    // Tim loai task theo ma; Main da kiem ma tu 1 den 4 nen luon tim thay
    public static TaskType getTaskTypeById(int taskTypeId) {
        TaskType result = null;

        // Duyet tung loai task de so ma
        for (TaskType taskType : TaskType.values()) {
            // Trung ma thi giu lai loai task do
            if (taskType.getId() == taskTypeId) {
                result = taskType;
            }
        }

        return result;
    }

    // Tra ve ma loai task
    public int getId() {
        return id;
    }

    // Tra ve ten loai task
    public String getName() {
        return name;
    }
}

package controller;

import constants.Message;
import dto.TaskDTO;
import repository.TaskRepository;
import view.TaskView;

/**
 * Nhan phieu DTO tu Main, goi Repository, roi dua ket qua cho View in 1 lan moi luong.
 * Bai chi them/xoa/hien (CRUD), khong co tinh toan nghiep vu nen KHONG co tang service.
 *
 * @author CuongThai Academy
 */
public class TaskController {

    // Kho task (Controller goi thang Repository vi bai khong co service)
    private TaskRepository taskRepository;

    // Man hinh in ket qua
    private TaskView taskView;

    // Constructor: tao kho va man hinh
    public TaskController() {
        taskRepository = new TaskRepository();
        taskView = new TaskView();
    }

    // Chuc nang 1: kho them task tu phieu Main da kiem, View bao ID moi
    public void addTask(TaskDTO taskDTO) {
        int taskId = taskRepository.addTask(taskDTO);

        // Bao them thanh cong kem ID vua cap
        taskView.setMessage(String.format(Message.SUCCESS_ADD_MESSAGE, taskId));
        taskView.display();
    }

    // Chuc nang 2: kho xoa theo ID trong phieu (khong co ID thi kho nem loi), View bao ket qua
    public void deleteTask(TaskDTO taskDTO) {
        // Kho xoa duoc thi bao thanh cong
        try {
            taskRepository.deleteTask(taskDTO.getId());
            taskView.setMessage(String.format(Message.SUCCESS_DELETE_MESSAGE, taskDTO.getId()));
        } catch (Exception e) {
            // Kho bao ID khong ton tai thi dua cau loi do cho View
            taskView.setMessage(e.getMessage());
        }

        taskView.display();
    }

    // Chuc nang 3: kho lay bang task (tang dan theo ID), View in bang hoac bao danh sach rong
    public void displayTasks() {
        // Kho rong thi chi bao rong, co task thi dua bang cho View
        if (taskRepository.isEmpty()) {
            taskView.setMessage(Message.ERROR_EMPTY);
        } else {
            // Co task: dua cac dong bang cho View
            taskView.setResponseList(taskRepository.getDataTasks());
        }

        taskView.display();
    }
}

