/**
 * Model 1 task cua du an: ID, loai, ten requirement, ngay, gio, nguoi lam, nguoi review.
 *
 * @author CuongThai Academy
 */
public class Task {

    // ID cua task
    private int id;

    // Loai task
    private TaskType taskType;

    // Ten requirement
    private String requirementName;

    // Ngay lam task
    private Date date;

    // Gio bat dau
    private double planFrom;

    // Gio ket thuc
    private double planTo;

    // Nguoi lam task
    private String assign;

    // Nguoi review task
    private String reviewer;

    // Tao task rong (JavaBean)
    public Task() {
    }

    // Tao task tu du lieu Main da kiem; ID se do Repository gan sau
    public Task(TaskType taskType, String requirementName, Date date, double planFrom,
            double planTo, String assign, String reviewer) {
        this.id = 0;
        this.taskType = taskType;
        this.requirementName = requirementName;
        this.date = date;
        this.planFrom = planFrom;
        this.planTo = planTo;
