    }

    // Gan nguoi review task
    public void setReviewer(String reviewer) {
        this.reviewer = reviewer;
    }
}

package repository;

import constants.Message;
import dto.ResponseDTO;
import dto.TaskDTO;
import java.util.ArrayList;
import java.util.List;
import model.Task;

/**
 * Kho giu danh sach task trong bo nho: them, xoa (tu kiem ID co hay khong), lay bang task.
 *
 * @author CuongThai Academy
 */
public class TaskRepository {

    // Danh sach task dang co, tang dan theo ID
    private List<Task> taskList;

    // ID cua task them gan nhat (de: ID = ID last task + 1)
    private int lastId;

    // Constructor: kho rong, chua co task nao
    public TaskRepository() {
        taskList = new ArrayList<>();
        lastId = 0;
    }

    // Them task moi tu phieu DTO, tra ve ID vua cap (ham addTask cua de)
    public int addTask(TaskDTO taskDTO) {
        Task task = new Task(taskDTO.getTaskType(), taskDTO.getRequirementName(),
                taskDTO.getDate(), taskDTO.getPlanFrom(), taskDTO.getPlanTo(),
                taskDTO.getAssign(), taskDTO.getReviewer());

        // Cap ID moi = ID task cuoi + 1 roi them vao cuoi danh sach
        lastId++;
        task.setId(lastId);
        taskList.add(task);

        return lastId;
    }

    // Xoa task theo ID; khong co ID do thi nem loi cho Controller bao lai (ham deleteTask cua de)
    public void deleteTask(int taskId) throws Exception {
        Task task = findById(taskId);

        // Khong tim thay task thi bao ID khong ton tai
        if (task == null) {
            throw new Exception(String.format(Message.ERROR_TASK_NOT_FOUND, taskId));
        }

        taskList.remove(task);
    }

    // Doi tung Task thanh 1 dong ResponseDTO de View in (ham getDataTasks cua de)
    public List<ResponseDTO> getDataTasks() {
        List<ResponseDTO> responseList = new ArrayList<>();

        // Duyet tung task (da tang dan theo ID vi luon them vao cuoi)
        for (Task task : taskList) {
            ResponseDTO responseDTO = new ResponseDTO();

            // Chep du lieu task sang dong bang; Time = To - From
            responseDTO.setId(task.getId());
            responseDTO.setRequirementName(task.getRequirementName());
            responseDTO.setTaskType(task.getTaskType());
            responseDTO.setDate(task.getDate());
            responseDTO.setTime(task.getPlanTo() - task.getPlanFrom());
            responseDTO.setAssign(task.getAssign());
            responseDTO.setReviewer(task.getReviewer());
            responseList.add(responseDTO);
        }

        return responseList;
    }

    // Kiem kho co rong khong
    public boolean isEmpty() {
        return taskList.isEmpty();
    }

    // Tim task theo ID; khong co thi tra null (chi dung trong kho)
    private Task findById(int taskId) {
        // Duyet tung task de so ID
        for (Task task : taskList) {
            // Trung ID thi tra ve task do
            if (task.getId() == taskId) {
                return task;
            }
        }

        return null;
    }
}

package utils;

import constants.Constants;
import constants.Message;
import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;

/**
 * Kiem tra dinh dang chu nguoi dung go vao. Sai thi nem Exception kem cau bao loi.
 *
 * @author CuongThai Academy
 */
public final class Validation {

    // Ngan khong cho tao doi tuong Validation
    private Validation() {
    }

    // Doi chu thanh so nguyen va kiem so nam trong [min, max]
    public static int getInt(String input, int min, int max) throws Exception {
        int number = 0;

        // Thu doi chu sang so nguyen (bo dau cach 2 dau truoc)
        try {
            number = Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // Go chu, so thuc hoac de trong thi bao phai nhap so nguyen
            throw new Exception(Message.ERROR_NOT_INTEGER);
        }

        // So nam ngoai khoang thi bao khoang dung
        if ((number < min) || (number > max)) {
            throw new Exception(String.format(Message.ERROR_INTEGER_RANGE, min, max));
        }

        return number;
    }

    // Doi chu thanh ID task (so nguyen tu 1 tro len)
    public static int getTaskId(String input) throws Exception {
        int taskId = 0;

        // Thu doi chu sang so nguyen (bo dau cach 2 dau truoc)
        try {
            taskId = Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // Go chu, so thuc hoac de trong thi bao phai nhap so nguyen
            throw new Exception(Message.ERROR_NOT_INTEGER);
        }

        // ID nho hon 1 thi bao ID phai tu 1 tro len
        if (taskId < Constants.TASK_ID_MIN) {
            throw new Exception(String.format(Message.ERROR_ID_RANGE, Constants.TASK_ID_MIN));
        }

        return taskId;
    }

    // Kiem ten requirement: bo dau cach 2 dau, khong duoc rong
    public static String getRequirementName(String input) throws Exception {
        String text = input.trim();

        // Rong (hoac chi co dau cach) thi bao loi
        if (text.isEmpty()) {
            throw new Exception(Message.ERROR_REQUIREMENT_EMPTY);
        }

        return text;
    }

    // Kiem ten nguoi (Assignee, Reviewer): chi chu cai khong dau, so, dau cach
    public static String getPersonName(String input) throws Exception {
        String text = input.trim();

        // Rong hoac co ky tu la thi bao loi
        if (!text.matches(Constants.REGEX_NAME_PEOPLE)) {
            throw new Exception(Message.ERROR_NAME_PEOPLE);
        }

        return text;
    }

    // Doi chu thanh ngay theo dang dd-MM-yyyy, chi nhan ngay co that
    public static Date getDate(String input) throws Exception {
        SimpleDateFormat dateFormat = new SimpleDateFormat(Constants.DATE_FORMAT_PATTERN);
        String text = input.trim();
        Date date = null;

        // Khong cho tu doi ngay sai (vi du 31-02 thanh 03-03)
        dateFormat.setLenient(false);

        // Thu doi chu sang ngay
        try {
            date = dateFormat.parse(text);
        } catch (ParseException e) {
            // De trong hoac sai dang thi bao loi
            throw new Exception(Message.ERROR_INVALID_DATE);
        }

        // In nguoc ngay ra chu phai giong chu da go (chan 1-2-2015, 26-06-2015abc)
        if (!dateFormat.format(date).equals(text)) {
            throw new Exception(Message.ERROR_INVALID_DATE);
        }

        return date;
    }

    // Doi chu thanh gio, kiem trong [min, max] va la so tron hoac nua tieng
    public static double getDouble(String input, double min, double max) throws Exception {
        double number = 0;

        // Thu doi chu sang so thuc (bo dau cach 2 dau truoc)
        try {
            number = Double.parseDouble(input.trim());
        } catch (NumberFormatException e) {
            // Go chu hoac de trong thi bao phai nhap so
            throw new Exception(Message.ERROR_NOT_REAL_NUMBER);
        }

        // Ngoai khoang (viet dang "khong nam trong" de chan ca NaN) thi bao khoang dung
        if (!((number >= min) && (number <= max))) {
            throw new Exception(String.format(Message.ERROR_PLAN_RANGE, min, max));
        }

        // Chia cho 0.5 con du thi khong phai so tron hoac nua tieng
        if ((number % Constants.PLAN_STEP) != 0) {
            throw new Exception(Message.ERROR_PLAN_STEP);
        }

        return number;
    }
}

package view;

import constants.Constants;
import constants.Message;
import dto.ResponseDTO;
import java.util.ArrayList;
import java.util.List;

/**
 * Man hinh: chi in ket qua Controller dua vao qua thuoc tinh; display() khong tham so,
 * goi 1 lan cho 1 luong: in cau thong bao, HOAC in bang task.
 *
 * @author CuongThai Academy
 */
public class TaskView {

    // Cac dong bang task can in
    private List<ResponseDTO> responseList;

    // Cau thong bao can in (rong thi in bang)
    private String message;

    // Constructor: chua co gi de in
    public TaskView() {
        responseList = new ArrayList<>();
        message = "";
    }

    // Controller dua cac dong bang vao
    public void setResponseList(List<ResponseDTO> responseList) {
        this.responseList = responseList;
    }

    // Controller dua cau thong bao vao
    public void setMessage(String message) {
        this.message = message;
    }

    // In ket qua cua 1 luong roi xoa cau thong bao de luong sau bat dau sach
    public void display() {
        // Co cau thong bao thi chi in cau do
        if (!message.isEmpty()) {
            System.out.println(message);
        } else {
            // Bang: tieu de, ten cot (cung dinh dang voi tung dong), roi tung dong task
            System.out.println(Message.TITLE_DISPLAY);
            System.out.println(String.format(Constants.TABLE_FORMAT, Message.COLUMN_ID,
                    Message.COLUMN_NAME, Message.COLUMN_TASK_TYPE, Message.COLUMN_DATE,
                    Message.COLUMN_TIME, Message.COLUMN_ASSIGNEE, Message.COLUMN_REVIEWER));

            // Moi task 1 dong
            for (ResponseDTO responseDTO : responseList) {
                System.out.println(responseDTO);
            }
        }

        message = "";
    }
}

